module min_trucks(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] C,\n    input [63:0] reach,\n    output reg [3:0] result,\n    output reg done\n);\n\n    reg [3:0] dp0 [0:255];\n    reg [3:0] dp1 [0:255];\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] INIT = 4'd1;\n    localparam [3:0] LOAD_I = 4'd2;\n    localparam [3:0] COPY = 4'd3;\n    localparam [3:0] PROCESS_MASK = 4'd4;\n    localparam [3:0] PROCESS_J = 4'd5;\n    localparam [3:0] UPDATE_DP = 4'd6;\n    localparam [3:0] SWAP = 4'd7;\n    localparam [3:0] FIND_RESULT = 4'd8;\n    localparam [3:0] FINISH = 4'd9;\n    reg [3:0] state;\n    reg [3:0] next_state;\n    reg [2:0] i;\n    reg [2:0] j;\n    reg [7:0] mask;\n    reg [7:0] addr;\n    reg [3:0] max_val;\n    wire mask_j = mask[j];\n    wire edge_ij = reach[i*8 + j];\n    integer k;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 4'd0;\n            i <= 3'd0;\n            j <= 3'd0;\n            mask <= 8'd0;\n            addr <= 8'd0;\n            max_val <= 4'd0;\n            for (k = 0; k < 256; k = k + 1) begin\n                dp0[k] <= 4'd0;\n                dp1[k] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= INIT;\n                end\n\n                INIT: begin\n                    dp0[0] <= 4'd0;\n                    i <= 3'd0;\n                    state <= LOAD_I;\n                end\n\n                LOAD_I: begin\n                    if (i < C) begin\n                        addr <= 8'd0;\n                        state <= COPY;\n                    end else begin\n                        addr <= 8'd0;\n                        max_val <= 4'd0;\n                        state <= FIND_RESULT;\n                    end\n                end\n\n                COPY: begin\n                    dp1[addr] <= dp0[addr];\n                    if (addr == 8'd255) begin\n                        mask <= 8'd0;\n                        state <= PROCESS_MASK;\n                    end else begin\n                        addr <= addr + 8'd1;\n                    end\n                end\n\n                PROCESS_MASK: begin\n                    if (mask == 8'd255) begin\n                        addr <= 8'd0;\n                        state <= SWAP;\n                    end else begin\n                        j <= 3'd0;\n                        state <= PROCESS_J;\n                    end\n                end\n\n                PROCESS_J: begin\n                    if (j < C) begin\n                        if (!mask_j && edge_ij) begin\n                            if (dp0[mask] != 0 || mask == 0) begin\n                                if (dp1[mask|(8'd1<<j)] <= dp0[mask] + 4'd1) begin\n                                    dp1[mask|(8'd1<<j)] <= dp0[mask] + 4'd1;\n                                end\n                            end\n                        end\n                        j <= j + 3'd1;\n                    end else begin\n                        mask <= mask + 8'd1;\n                        state <= PROCESS_MASK;\n                    end\n                end\n\n                SWAP: begin\n                    dp0[addr] <= dp1[addr];\n                    if (addr == 8'd255) begin\n                        i <= i + 3'd1;\n                        state <= LOAD_I;\n                    end else begin\n                        addr <= addr + 8'd1;\n                    end\n                end\n\n                FIND_RESULT: begin\n                    if (addr == 8'd255) begin\n                        result <= C - max_val;\n                        state <= FINISH;\n                    end else begin\n                        if (dp0[addr] > max_val) begin\n                            max_val <= dp0[addr];\n                        end\n                        addr <= addr + 8'd1;\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule